// ============================================================
// Aervo QuickBooks Integration — Margin Calculation
// File: routes/analytics/margin.js
// See quickbooks-integration-spec.md section 5.
//
// The GET route only ever reads from margin_snapshots — per spec,
// margins are "regenerated by the nightly sync", not computed live
// on every request. calculateMargins() is the piece that actually
// computes them; it's exported here and called from the end of
// scripts/sync-quickbooks.js, the same way autoMatchProducts() is
// shared between routes/products/costMapping.js and the sync script.
// ============================================================

const express = require('express');

function round2(n) {
  return Math.round(n * 100) / 100;
}

// Formats a UTC-midnight instant as a 'YYYY-MM-DD' string. Needed
// before binding to a DATE column — passing the raw JS Date lets
// node-pg's client-side serialization use the host's LOCAL calendar
// date instead of the UTC one, which can shift the stored date by a
// day depending on the host's timezone.
function toDateString(date) {
  return date.toISOString().slice(0, 10);
}

// Monday-based "week to date" — Monday 00:00 UTC through today 00:00 UTC.
// Each ISO week gets its own margin_snapshots row (period_start = that
// Monday), so once a week ends its row is frozen and later weeks don't
// touch it — exactly what the digest (section 6) needs to diff "this
// week" against "last week".
//
// Computed in UTC explicitly (not local Date methods) because the DB
// session runs in UTC (confirmed via `SHOW timezone`) while this script
// can run on a host in any timezone — using local time here would shift
// the boundary by the host's UTC offset and clip hours off "today".
function getCurrentWeekBounds() {
  const now = new Date();
  const day = now.getUTCDay(); // 0 = Sunday .. 6 = Saturday
  const diffToMonday = day === 0 ? 6 : day - 1;

  const periodStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - diffToMonday));
  const periodEnd = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));

  return { periodStart, periodEnd };
}

// QuickBooks Online's ProfitAndLoss report is a nested Row tree, but
// the top-level rows each carry a "group" (Income, COGS, GrossProfit,
// Expenses, ...) with a Summary total — see quickbooks_pnl_snapshots.
// Phase 1 doesn't map Aervo product categories to QBO accounts, so the
// "category average" fallback from the spec is approximated as a
// single blended COGS-to-revenue ratio for the whole business.
function cogsRatioFromPnl(reportData) {
  const rows = reportData?.Rows?.Row || [];
  let income = 0;
  let cogs = 0;

  for (const row of rows) {
    const total = parseFloat(row.Summary?.ColData?.[1]?.value);
    if (Number.isNaN(total)) continue;
    if (row.group === 'Income') income = total;
    if (row.group === 'COGS') cogs = total;
  }

  return income > 0 ? cogs / income : 0;
}

// Computes and caches this week's per-product margins for one user.
// Cost priority per spec section 5:
//   1. Mapped product, QuickBooks item has a direct PurchaseCost -> hard number
//   2. Mapped product, no direct cost -> average unit cost from that
//      item's Purchase/Bill lines -> still a hard number
//   3. Anything else (unmatched, or mapped with no cost data at all)
//      -> blended COGS ratio from the latest P&L pull -> estimated: true
async function calculateMargins(pool, userId) {
  const { periodStart, periodEnd } = getCurrentWeekBounds();
  const periodEndExclusive = new Date(periodEnd);
  periodEndExclusive.setDate(periodEndExclusive.getDate() + 1);

  const soldProducts = await pool.query(
    `SELECT
       si.product_id AS aervo_product_id,
       p.name,
       p.sku,
       SUM(si.quantity) AS quantity_sold,
       SUM(si.line_total) AS revenue,
       m.match_type,
       m.quickbooks_item_id
     FROM aervo_sale_items si
     JOIN aervo_sales s ON s.id = si.sale_id
     JOIN aervo_products p ON p.id = si.product_id
     LEFT JOIN product_cost_mappings m
       ON m.aervo_product_id = p.id AND m.user_id = $1
     WHERE s.merchant_id = $1
       AND s.sale_date >= $2
       AND s.sale_date < $3
     GROUP BY si.product_id, p.name, p.sku, m.match_type, m.quickbooks_item_id`,
    [userId, periodStart, periodEndExclusive]
  );

  const [{ rows: items }, { rows: purchaseAverages }, pnlResult] = await Promise.all([
    pool.query(
      `SELECT quickbooks_item_id, purchase_cost FROM quickbooks_items WHERE user_id = $1`,
      [userId]
    ),
    pool.query(
      `SELECT quickbooks_item_id, AVG(unit_cost) AS avg_unit_cost
       FROM quickbooks_purchases
       WHERE user_id = $1 AND quickbooks_item_id IS NOT NULL AND unit_cost IS NOT NULL
       GROUP BY quickbooks_item_id`,
      [userId]
    ),
    pool.query(
      `SELECT data FROM quickbooks_pnl_snapshots WHERE user_id = $1 ORDER BY period_start DESC LIMIT 1`,
      [userId]
    ),
  ]);

  const directCostByItemId = new Map(
    items.filter((i) => parseFloat(i.purchase_cost) > 0).map((i) => [i.quickbooks_item_id, parseFloat(i.purchase_cost)])
  );
  const avgCostByItemId = new Map(
    purchaseAverages.map((p) => [p.quickbooks_item_id, parseFloat(p.avg_unit_cost)])
  );
  const cogsRatio = pnlResult.rows.length ? cogsRatioFromPnl(pnlResult.rows[0].data) : 0;

  const products = soldProducts.rows.map((row) => {
    const revenue = parseFloat(row.revenue) || 0;
    const quantitySold = parseFloat(row.quantity_sold) || 0;
    const isMapped = row.match_type === 'auto' || row.match_type === 'manual';

    let unitCost = null;
    if (isMapped && row.quickbooks_item_id) {
      if (directCostByItemId.has(row.quickbooks_item_id)) {
        unitCost = directCostByItemId.get(row.quickbooks_item_id);
      } else if (avgCostByItemId.has(row.quickbooks_item_id)) {
        unitCost = avgCostByItemId.get(row.quickbooks_item_id);
      }
    }

    let cost;
    let estimated;
    if (unitCost != null) {
      cost = unitCost * quantitySold;
      estimated = false;
    } else {
      cost = revenue * cogsRatio;
      estimated = true;
    }

    const marginPct = revenue > 0 ? ((revenue - cost) / revenue) * 100 : null;

    return {
      aervo_product_id: row.aervo_product_id,
      name: row.name,
      sku: row.sku,
      quantity_sold: quantitySold,
      revenue: round2(revenue),
      cost: round2(cost),
      margin_pct: marginPct != null ? round2(marginPct) : null,
      estimated,
    };
  });

  await pool.query(
    `INSERT INTO margin_snapshots (user_id, period_type, period_start, period_end, data, generated_at)
     VALUES ($1, 'week', $2, $3, $4, NOW())
     ON CONFLICT (user_id, period_type, period_start) DO UPDATE SET
       period_end   = EXCLUDED.period_end,
       data         = EXCLUDED.data,
       generated_at = NOW()`,
    [userId, toDateString(periodStart), toDateString(periodEnd), JSON.stringify(products)]
  );

  return { periodStart, periodEnd, productCount: products.length };
}

module.exports = function (pool, authenticateToken) {
  const router = express.Router();

  // ============================================================
  // GET /api/analytics/margin?period=week
  // Reads the cached snapshot only — phase 1 only ever computes
  // 'week' periods, so any other value just returns no data yet.
  // ============================================================
  router.get('/api/analytics/margin', authenticateToken, async (req, res) => {
    const userId = req.user.userId;
    const periodType = req.query.period || 'week';

    try {
      const result = await pool.query(
        `SELECT period_start::text AS period_start, period_end::text AS period_end, data, generated_at
         FROM margin_snapshots
         WHERE user_id = $1 AND period_type = $2
         ORDER BY period_start DESC
         LIMIT 1`,
        [userId, periodType]
      );

      if (!result.rows.length) {
        return res.json({
          success: true,
          generated: false,
          message: 'No margin data yet — this is computed by the nightly QuickBooks sync.',
          products: [],
        });
      }

      const row = result.rows[0];
      res.json({
        success: true,
        generated: true,
        period_type: periodType,
        period_start: row.period_start,
        period_end: row.period_end,
        generated_at: row.generated_at,
        products: row.data,
      });
    } catch (err) {
      console.error('Error fetching margin snapshot', { userId, error: err.message });
      res.status(500).json({ success: false, message: 'Internal server error' });
    }
  });

  return router;
};

module.exports.calculateMargins = calculateMargins;
